import unittest

from solution import render_artifacts


class RenderArtifactsTests(unittest.TestCase):
    def test_rendering_and_sorted_artifact_order(self):
        model = {"name": "Ada", "count": 3}
        templates = {"z.txt": "{name}:{count}", "a.txt": "Hello {name}", "m.txt": "{{{name}}}"}
        model_before = dict(model)
        templates_before = dict(templates)
        result = render_artifacts(model, templates)
        self.assertEqual(result, {"a.txt": "Hello Ada", "m.txt": "{Ada}", "z.txt": "Ada:3"})
        self.assertEqual(list(result), ["a.txt", "m.txt", "z.txt"])
        self.assertEqual(model, model_before)
        self.assertEqual(templates, templates_before)
        self.assertIsNot(result, templates)

    def test_empty_inputs_and_empty_template(self):
        self.assertEqual(render_artifacts({}, {}), {})
        self.assertEqual(render_artifacts({}, {"empty": ""}), {"empty": ""})

    def test_invalid_top_level_and_entries(self):
        cases = [
            ([], {}), ({}, []), ({"not-valid": "x"}, {}), ({1: "x"}, {}),
            ({"x": True}, {}), ({"x": 1.5}, {}), ({"x": []}, {}),
            ({}, {"": "x"}), ({}, {1: "x"}), ({}, {"a": 3}),
        ]
        for model, templates in cases:
            with self.subTest(model=model, templates=templates), self.assertRaises(ValueError):
                render_artifacts(model, templates)

    def test_disallowed_replacement_field_forms(self):
        bad = ["{user.name}", "{items[0]}", "{name!r}", "{name:>10}", "{0}", "{}"]
        for template in bad:
            with self.subTest(template=template), self.assertRaises(ValueError):
                render_artifacts({"name": "Ada", "user": "u", "items": "x"}, {"a": template})

    def test_missing_field_error_names_field(self):
        with self.assertRaises(ValueError) as caught:
            render_artifacts({"present": "yes"}, {"a": "{missing}"})
        self.assertIn("missing", str(caught.exception))

    def test_malformed_braces_raise_value_error(self):
        for template in ("{name", "name}"):
            with self.subTest(template=template), self.assertRaises(ValueError):
                render_artifacts({"name": "Ada"}, {"a": template})


if __name__ == "__main__":
    unittest.main()

